    def __init__(self, numero, superficie, facturacion):
        self.numero = numero
        self.superficie = superficie
        self.facturacion = facturacion

    @abstractmethod
    def resultado_comercial(self):
        pass

    @abstractmethod
    def es_rentable(self):
        pass

    @abstractmethod
    def tipo(self):
        pass

